 void folderMenu(){if(busy)return;juce::PopupMenu menu,moves;menu.addItem(1,"New folder...");bool selected=currentFolder!=library.base&&!allFolders;menu.addItem(2,"Rename folder...",selected);menu.addItem(3,text("Delete folder..."),selected);juce::Array<juce::File> targets;targets.add(library.base);moves.addItem(100,"Library root");for(auto& folder:library.folders)if(folder!=currentFolder&&!folder.isAChildOf(currentFolder)){targets.add(folder);moves.addItem(99+targets.size(),folder.getRelativePathFrom(library.base));}menu.addSubMenu("Move folder",moves,selected);auto safe=juce::Component::SafePointer<AssetBrowser>(this);auto folder=currentFolder;menu.showMenuAsync(juce::PopupMenu::Options().withTargetComponent(&folderButton),[safe,folder,targets](int choice){if(!safe)return;if(choice==1)safe->prompt("New folder","",[safe,folder](juce::String name){if(!safe)return;juce::File created;auto result=safe->library.createFolder(folder,name,created);safe->feedback(result,"Folder created");});else if(choice==2)safe->prompt("Rename folder",folder.getFileName(),[safe,folder](juce::String name){if(!safe)return;juce::File renamed;auto result=safe->library.changeFolder(folder,folder.getParentDirectory(),name,renamed);if(result.wasOk()){safe->updateLoaded(folder,renamed);safe->currentFolder=renamed;}safe->feedback(result,"Folder renamed");});else if(choice==3)safe->removeSelectedFolder();else if(choice>=100&&choice-100<targets.size())safe->movePath(folder,targets[choice-100],true);});}
