 void categoryMenu(){if(busy)return;juce::PopupMenu menu,rename,remove;menu.addItem(1,"Add category...");auto categories=library.categories;for(int i=0;i<categories.size();++i){rename.addItem(100+i,categories[i]);remove.addItem(1000+i,categories[i]);}menu.addSubMenu("Rename category",rename,categories.size()>0);menu.addSubMenu("Remove category",remove,categories.size()>0);auto safe=juce::Component::SafePointer<AssetBrowser>(this);menu.showMenuAsync(juce::PopupMenu::Options().withTargetComponent(&categoryButton),[safe,categories](int choice){if(!safe)return;if(choice==1)safe->prompt("New category","",[safe](juce::String name){if(safe)safe->feedback(safe->library.editCategory({},name),"Category created");});else if(choice>=1000&&choice-1000<categories.size())safe->feedback(safe->library.editCategory(categories[choice-1000],{}),"Category and assignments removed");else if(choice>=100&&choice-100<categories.size()){auto old=categories[choice-100];safe->prompt("Rename category",old,[safe,old](juce::String name){if(safe)safe->feedback(safe->library.editCategory(old,name),"Category renamed");});}});}
