 void loadSelected(){if(busy)return;if(auto* pointer=selected()){auto entry=*pointer;if(library.kind==AssetKind::Fx){juce::var doc;auto result=FxLibrary::read(entry.file,doc);if(result.wasOk())result=FxLibrary::apply(processor,doc,osc);if(result.wasOk()&&processor.effectOnly){PresetMetadata metadata;metadata.name=entry.name;metadata.author=entry.author;metadata.description=entry.description;metadata.notes=entry.notes;metadata.tags=entry.tags;metadata.category=entry.category;metadata.rating=entry.rating;processor.state.state.setProperty("fxPresetFile",entry.file.getFullPathName(),nullptr);processor.state.state.setProperty("fxPresetName",entry.name,nullptr);processor.state.state.setProperty("fxHeaderMetadata",juce::JSON::toString(metadata.toJson()),nullptr);}status.setText(result.wasOk()?"Loaded into "+fxTarget.getText()+": "+entry.name:result.getErrorMessage(),juce::dontSendNotification);return;}juce::String error;if(processor.loadOscillatorAsset(osc,entry.file,library.kind==AssetKind::Wavetable?0:4,error)){processor.state.state.setProperty("osc"+juce::String(osc+1)+"LibraryAsset",entry.storage.getFullPathName(),nullptr);if(library.kind==AssetKind::Multisample){auto old=std::atomic_load(&processor.importedAssets);auto assets=std::make_shared<ImportedAssets>(*old);auto expansion=std::make_shared<Expansion>(*old->expansion);expansion->osc[osc].sampleName=entry.name;assets->expansion=expansion;std::atomic_store(&processor.importedAssets,std::shared_ptr<const ImportedAssets>(assets));}status.setText("Loaded into OSC "+juce::String::charToString('A'+osc)+": "+entry.name,juce::dontSendNotification);}else status.setText(error,juce::dontSendNotification);}}
 void choose(bool directory){if(busy)return;bool multi=library.kind==AssetKind::Multisample,fx=library.kind==AssetKind::Fx;chooser=std::make_unique<juce::FileChooser>(directory?"Library folder import":fx?"Import FX preset or ZIP":multi?"Import SFZ or ZIP":"Import WAV or ZIP",juce::File(),directory?"*":fx?"*.ncfx;*.zip":multi?"*.sfz;*.zip":"*.wav;*.zip");auto safe=juce::Component::SafePointer<AssetBrowser>(this);chooser->launchAsync(juce::FileBrowserComponent::openMode|(directory?juce::FileBrowserComponent::canSelectDirectories:juce::FileBrowserComponent::canSelectFiles),[safe](const juce::FileChooser& fc){if(!safe||fc.getResult()==juce::File())return;auto source=fc.getResult();safe->busy=true;safe->importFolder.setEnabled(false);safe->importFile.setEnabled(false);safe->status.setText("Importing...",juce::dontSendNotification);auto base=safe->library.base;auto kind=safe->library.kind;juce::Thread::launch([safe,source,base,kind]{auto result=kind==AssetKind::Fx?FxLibrary::importPack(source,base):kind==AssetKind::Wavetable?WavetableLibrary::importPack(source,base):AssetLibrary::importMultisamples(source,base);juce::MessageManager::callAsync([safe,result]{if(!safe)return;safe->busy=false;safe->importFolder.setEnabled(true);safe->importFile.setEnabled(true);safe->rescan();safe->status.setText(result.error.isEmpty()?"Imported "+juce::String(result.added)+" / skipped "+juce::String(result.skipped):result.error,juce::dontSendNotification);});});});}
 void saveFxPreset(int slot){auto doc=FxLibrary::capture(processor,osc,slot);auto values=details();values.author.clear();values.description.clear();values.notes.clear();values.tags.clear();values.rating=0;values.category=slot<0?"FX Chains":"Effects";auto name=slot<0?juce::String("New effect chain"):FxLibrary::summary(doc).replace(" / "," - ").replace("/","-");prompt(slot<0?"Save effect chain":"Save single effect",name,[this,doc,values](juce::String name)mutable{values.name=name;juce::File saved;feedback(FxLibrary::save(currentFolder,values,doc,saved),"FX preset saved",saved);});}
 void chooseFxToSave(){juce::PopupMenu menu;juce::Array<int> slots;for(auto& entry:processor.rack()->entries)if(entry.bus==osc){slots.add(entry.slot);menu.addItem(slots.size(),juce::String(slots.size())+"  "+fxDefinitions()[(size_t)entry.type].name);}if(slots.isEmpty()){status.setText("The destination rack has no effect to save.",juce::dontSendNotification);return;}auto safe=juce::Component::SafePointer<AssetBrowser>(this);menu.showMenuAsync(juce::PopupMenu::Options().withTargetComponent(&saveFx),[safe,slots](int choice){if(safe&&choice>0&&choice<=slots.size())safe->saveFxPreset(slots[choice-1]);});}

