 // Reload external library edits without discarding an in-progress metadata draft.
 void syncFxLibrary(){if(library.kind!=AssetKind::Fx||busy||fxDetailsDirty())return;for(auto& dialog:dialogs)if(dialog)return;auto signature=librarySignature();if(signature!=fxLibrarySignature){juce::File path;if(auto* entry=selected())path=entry->storage;rescan(path);}}
