 void paint(juce::Graphics& g)override{nd::Scope suitScope("library");using namespace juce;libraryChrome(g,library.kind==AssetKind::Fx?"FX LIBRARY":library.kind==AssetKind::Wavetable?"WAVETABLE LIBRARY":"MULTISAMPLE LIBRARY",(library.kind==AssetKind::Fx?fxTarget.getText():"OSC "+String::charToString('A'+osc))+" / "+String(library.folders.size())+" folders / "+String(library.entries.size())+" entries");g.setColour(nd::colour(nd::colour(Colour(0xff243442))));g.fillRect(232,64,645,30);g.setColour(nd::colour(nd::colour(Colour(NEXUM_UI_ACCENT))));g.setFont(FontOptions(nd::number("fontSize",11.5f),Font::bold));g.drawText("NAME",241,64,210,30,Justification::centredLeft);g.drawText("CATEGORY",463,64,100,30,Justification::centredLeft);g.drawText("AUTHOR",571,64,128,30,Justification::centredLeft);g.drawText(library.kind==AssetKind::Fx?"FX":library.kind==AssetKind::Wavetable?"FRAMES":"ZONES",707,64,70,30,Justification::centredLeft);g.drawText("RATING",781,64,88,30,Justification::centred);g.setColour(nd::colour(nd::colour(Colour(0xff344b5d))));g.drawRect(232,64,645,350,1);for(int x:{462,570,708,784})g.drawVerticalLine(x,64,94);Rectangle<float> r(232,426,645,180);UiStyle::plot(g,r);g.setColour(nd::colour(nd::colour(Colour(0xff344b5d))));if(library.kind!=AssetKind::Fx)g.drawHorizontalLine((int)r.getCentreY(),r.getX(),r.getRight());if(library.kind==AssetKind::Fx){libraryText(g,"DESTINATION RACK",{605,440,90,28},10);if(auto* entry=selected()){juce::var doc;auto result=FxLibrary::read(entry->file,doc);libraryText(g,entry->name,{248,438,345,28},16,UiStyle::blue());g.setColour(nd::colour(nd::colour(Colour(0xffb6cada))));g.setFont(FontOptions(nd::number("fontSize",12)));g.drawFittedText(result.wasOk()?FxLibrary::summary(doc):result.getErrorMessage(),{248,480,610,50},Justification::topLeft,3);libraryText(g,doc.getProperty("scope",{}).toString()=="effect"?"Single effect: appended to the destination rack.":"Effect chain: replaces only the selected destination rack.",{248,539,610,24},10);}else libraryText(g,"Save and import individual effects or chains. Double-click to load.",{248,480,610,50},12);}else if(preview){Path path;for(int i=0;i<512;++i){float x=r.getX()+i/511.f*r.getWidth(),y=r.getCentreY()-preview->sample(0,i/511.,1,44100)*r.getHeight()*.44f;if(i==0)path.startNewSubPath(x,y);else path.lineTo(x,y);}UiStyle::fillCurve(g,path,r,r.getCentreY());g.setColour(nd::colour(nd::colour(Colour(NEXUM_UI_ACCENT))));g.strokePath(path,PathStrokeType(nd::number("stroke",1.5f)));}else if(multiPreview){for(auto& region:multiPreview->osc[0].regions){Rectangle<float> zone(r.getX()+region.lo/128.f*r.getWidth(),r.getY()+(127-region.highVelocity)/127.f*r.getHeight(),(region.hi-region.lo+1)/128.f*r.getWidth(),jmax(2.f,(region.highVelocity-region.lowVelocity+1)/127.f*r.getHeight()));g.setColour(nd::colour(nd::colour(Colour(NEXUM_UI_ACCENT)).withAlpha(.3f)));g.fillRect(zone);g.setColour(nd::colour(nd::colour(Colour(NEXUM_UI_ACCENT))));g.drawRect(zone,1);}g.setColour(nd::colour(Colours::white));g.setFont(FontOptions(11.f));g.drawText("KEY / VELOCITY ZONES",r.reduced(8),Justification::bottomLeft);}else{g.setColour(nd::colour(nd::colour(Colour(0xff899aa5))));g.setFont(FontOptions(12.f));g.drawText(library.kind==AssetKind::Wavetable?"Add WAV wavetables as a folder, ZIP or file":"Add SFZ instruments and their samples as a folder, ZIP or SFZ",r,Justification::centred);}}
 static juce::DialogWindow* open(SynthProcessor& p,int osc,AssetKind kind,juce::Component* parent){juce::DialogWindow::LaunchOptions options;options.content.setOwned(new AssetBrowser(p,osc,kind));options.dialogTitle=kind==AssetKind::Fx?"FX Library":kind==AssetKind::Wavetable?"Wavetable Library":"Multisample Library";options.dialogBackgroundColour=nd::colour(juce::Colour(0xff1e2b36));options.escapeKeyTriggersCloseButton=true;options.useNativeTitleBar=true;options.resizable=false;options.componentToCentreAround=parent;return options.launchAsync();}
